from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

class ListingLinks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.href = None
        self.parts = []
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.href = dict(attrs).get('href')
            self.parts = []

    def handle_data(self, data):
        if self.href:
            self.parts.append(data)

    def handle_endtag(self, tag):
        if tag != 'a' or not self.href:
            return
        url = urlsplit(urljoin('https://jobs.wordpress.net/', self.href))
        text = ' '.join(' '.join(self.parts).split())
        if url.scheme == 'https' and url.netloc == 'jobs.wordpress.net' and '/job/' in url.path and len(url.path.strip('/').split('/')) >= 2:
            key = url._replace(query='', fragment='').geturl()
            if text and len(text) > len(self.links.get(key, '')):
                self.links[key] = text[:200]
        self.href = None

root = Path('products/services/wordpress-migration-paid-qa')
raw = (root / 'raw/wordpress-jobs-index.html').read_bytes()
parser = ListingLinks()
parser.feed(raw.decode('utf-8', errors='replace'))
terms = re.compile(r'\b(?:migrat\w*|import\w*|export\w*|content transfer|replatform\w*)\b', re.I)
leads = [{'url': url, 'title': title} for url, title in parser.links.items() if terms.search(title) or terms.search(re.sub(r'[-_/]', ' ', urlsplit(url).path))]
result = {'source': 'https://jobs.wordpress.net/', 'source_task': 'TASK-179541722200', 'source_sha256': hashlib.sha256(raw).hexdigest(), 'recognized_listing_links': len(parser.links), 'candidate_count': len(leads), 'candidate_links': leads[:12], 'scope': 'Title and URL extraction from one saved index. An empty result can reflect link markup or title wording. Original listings must establish dates, paid scope and response terms.'}
output = root / 'migration-title-candidates.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == result
print(json.dumps(result, ensure_ascii=False))
